/**
 * tauri-updater.js — wrapper do plugin updater do Tauri.
 *
 * Esta versão NÃO importa de "@tauri-apps/api/core" (que não funciona no browser
 * sem bundler — causa erro "Failed to resolve module specifier").
 * Em vez disso, usa window.__TAURI__.core.invoke que vem exposto pelo
 * withGlobalTauri: true no tauri.conf.json.
 *
 * Uso:
 *   const { check } = await import('/js/tauri-updater.min.js')
 *   const update = await check()
 *   if (update) {
 *     await update.downloadAndInstall()
 *   }
 */

// Pega invoke do global (window.__TAURI__.core.invoke)
function getInvoke() {
  const tauri = window.__TAURI__ || window.__TAURI_INTERNALS__;
  if (!tauri) throw new Error('Tauri não está disponível (window.__TAURI__)');
  if (!tauri.core || !tauri.core.invoke) {
    throw new Error('window.__TAURI__.core.invoke não disponível — verifique withGlobalTauri no tauri.conf.json');
  }
  return tauri.core.invoke;
}

// Pega Channel (se disponível; senão mock)
function getChannel() {
  const tauri = window.__TAURI__ || window.__TAURI_INTERNALS__;
  if (tauri?.core?.Channel) return tauri.core.Channel;
  // Mock: Channel é só pra callbacks de progresso de download.
  return class MockChannel {
    constructor() { this.onmessage = null; }
  };
}

function convertToRustHeaders(options) {
  if (options?.headers) {
    options.headers = Array.from(new Headers(options.headers).entries());
  }
}

const Channel = getChannel();

class Update {
  constructor(data) {
    this.rid = data.rid;
    this.available = true;
    this.currentVersion = data.currentVersion;
    this.version = data.version;
    this.date = data.date;
    this.body = data.body;
    this.rawJson = data.rawJson;
    this.downloadedBytes = undefined;
  }

  async download(onEvent, options) {
    const invoke = getInvoke();
    convertToRustHeaders(options);
    const channel = new Channel();
    if (onEvent) channel.onmessage = onEvent;
    const result = await invoke('plugin:updater|download', {
      onEvent: channel,
      rid: this.rid,
      ...options,
    });
    this.downloadedBytes = { rid: result, close: async () => {} };
  }

  async install(options) {
    const invoke = getInvoke();
    if (!this.downloadedBytes) throw new Error('Update.install chamado antes de Update.download');
    await invoke('plugin:updater|install', {
      updateRid: this.rid,
      bytesRid: this.downloadedBytes.rid,
      ...options,
    });
    this.downloadedBytes = undefined;
  }

  async downloadAndInstall(onEvent, options) {
    const invoke = getInvoke();
    convertToRustHeaders(options);
    const channel = new Channel();
    if (onEvent) channel.onmessage = onEvent;
    await invoke('plugin:updater|download_and_install', {
      onEvent: channel,
      rid: this.rid,
      ...options,
    });
  }

  async close() {
    if (this.downloadedBytes?.close) await this.downloadedBytes.close();
  }
}

async function check(options) {
  const invoke = getInvoke();
  convertToRustHeaders(options);
  const result = await invoke('plugin:updater|check', { ...options });
  return result ? new Update(result) : null;
}

// Export ESM (pra `await import('/js/tauri-updater.min.js')` funcionar)
export { Update, check };
